INSERT INTO `criteria` (`id`, `item_no`, `category`, `max_score`, `description`, `active`) VALUES (36,1,0,2,'บอร์ด 5ส : เอกสารในบอร์ด มีความเป็นปัจจุบัน ครบ ถูกต้องทุกช่อง = 2 คะแนน, ไม่ครบ = 1 คะแนน',1),(37,2,0,2,'มีการทำไคเซ็นต์ของพื้นที่อย่างน้อย 2 เรื่องต่อเดือนต่อพื้นที่ = 2 คะแนน, น้อยกว่า 2 = 1 คะแนน1',1),(38,3,0,1,'ผู้นำหน่วย นำทีมงานเข้ารับการตรวจได้ถูกต้อง เป็นระเบียบ มีวินัย และสวมปลอกแขนผู้นำหน่วย1',1),(39,4,0,1,'Lay out ในพื้นที่ มีการ Update เป็นปัจจุบัน มีผู้เข้าใหม่ และไม่มีผู้ลาออก/โยกย้ายอยู่ในพื้นที่1',1),(40,5,0,1,'มีมาตรฐานการทำความสะอาดพื้นที่ และตรวจตามใบ Check Sheet ครบ และมีการลงบันทึกถูกต้อง1',1),(41,6,0,3,'เครื่องจักร รวมถึงรถส่งสินค้า รถโฟล์คลิฟท์ เครน มีสีสันสดใส สะอาด ไม่มีรอยขูดขีด ถลอก บุบ ยุบ แตก ไม่มีคราบสกปรก หยากไย่ ขี้นก2',1),(42,7,0,3,'อุปกรณ์ต่อพ่วง (เครน,ราง,คานโหลด) ท่อต่างๆมีสีสดใส ไม่มีคราบน้ำมัน ไม่มีรอยถลอก บุบ ยุบ แตก ชำรุด',1),(43,8,0,3,'รอบเครื่องจักรไม่พบน้ำมันกระเด็นออกนอกเครื่อง,น้ำมันรั่วหยด รอบเครื่องไม่มีฝุ่น ไม่มีหยากไย่ คราบสกปรกบนพื้น ไม่มีสิ่งของไม่เกี่ยวข้องวางอยู่โดยรอบเครื่องจักรและอุปกรณ์ต่อพ่วง',1),(44,9,0,2,'มีแผนการทำ AM และบันทึกในใบ Check sheet',1),(45,10,0,2,'มีป้ายชี้บ่งชื่อเครื่องจักร,  มีแผนผังกำหนดตำแหน่งการวางเครืองจักร',1),(46,11,0,1,'มีถังดับเพลิงประจำจุดวางให้เห็นชัดเจน ทำความสะอาดไม่มีคราบฝุ่น มีการตรวจสอบทุกเดือน',1),(47,12,0,1,'มีระบุผู้รับผิดชอบประจำเครื่องไว้อย่างชัดเจน สามารถมองเห็นเด่นชัด มีรูปผู้รับผิดชอบแสดง',1),(48,13,0,1,'มี STD และ M/C Check Sheet ,มีการตรวจ Update เป็นประจำทุกวัน',1),(49,14,0,2,'ด้านบน ข้างใต้ และในลิ้นชัก โต๊ะทำงาน / โต๊ะ Control  ไม่มีสิ่งของไม่จำเป็น/ไม่เกี่ยวข้องกับงานอยู่',1),(50,15,0,2,'อุปกรณ์ต่อพ่วง (เครน,ราง,คานโหลด) ท่อต่างๆมีสีสดใส ไม่มีคราบน้ำมัน ไม่มีรอยถลอก บุบ ยุบ แตก ชำรุด',1),(51,16,0,2,'มีระบุชื่อผู้รับผิดชอบ ติดอยู่ที่โต๊ะทำงาน / โต๊ะ Control และสามารถมองเห็นได้ชัดเจน (ไม่เล็กเกินไป)',1),(52,17,0,2,'โต๊ะ ทำงาน / โต๊ะ Control  ไม่มีฝุ่น ไม่มีหยากไย่ สะอาด ไม่มีคราบกระดาษกาว สก๊อตเทป สติ๊กเกอร์',1),(53,18,0,2,'พัดลมที่มีอยู่ในพื้นที่ทำงาน สะอาด ไม่มีฝุ่น หยากไย่ ไม่มีส่วนใดส่วนหนึ่งชำรุด แตก หัก บิดงอ',1),(54,19,0,1,'ตู้ / ชั้นวางของ ไม่มีล่วนใดชำรุด, ไม่วางสิ่งของบนหลังตู้ สะอาด ไม่มีสต๊กเกอร์ ไม่มีหยากไย่ และฝุ่น',1),(55,20,0,1,'กำหนดจุดวางของชัดเจน มีป้ายชี้บ่ง,วางสิ่งของเป็นระเบียบถูก้องตามที่กำหนด',1),(56,21,0,1,'อุปกรณ์ต่อพ่วง (เครน,ราง,คานโหลด) ท่อต่างๆมีสีสดใส ไม่มีคราบน้ำมัน ไม่มีรอยถลอก บุบ ยุบ แตก ชำรุด',1),(57,22,0,1,'พื้น/ทางเดิน ไม่มีขยะ ไม่สกปรก  เส้นทางเดินไม่สกปรก ไม่มีคราบน้ำมัน สีเส้นชัดเจน ไม่ลอก ไม่ถลอก',1),(58,23,0,1,'ไม่มีการสิ่งของ อุปกรณ์ วางกีดขวาง วางล้ำ พื้นที่ทางเดิน รวมถึงมาสายไฟพาดผ่านพื้นที่ทางเดิน',1),(59,24,0,1,'ไม่มีสายไฟระโยงระยาง, ไม่แขวนสิ่งของที่ไม่จำเป็น',1),(60,25,0,1,'ผนัง ฝ้า เพดาน ไม่มีหยากไย่ ไม่มีรอยขีดเขียน  สติ๊กเกอร์ คราบกาว รูปภาพต่างๆ ยกเว้นปฏิทินการทำงาน',1),(61,26,0,1,'หลอดไฟ อุปกรณ์ไฟฟ้า พัดลม/เครื่องปรับอากาศ ไม่มีชำรุด ไม่มีฝุ่น หยากไย่ คราบสกปรกต่างๆ',1),(62,27,0,1,'อุปกรณ์ไฟสัญญาณ ,ไซเลน ติดไม่มีการชำรุด',1),(63,28,0,1,'บริเวณโดยรอบ พื้นสะอาด ไม่มีขยะล้นถัง จัดเก็บอุปกรณ์ได้ดี ถูกต้อง ไม่วางไว้ลอยๆ หรือกองไว้',1),(64,29,0,1,'ถังใส่ขยะ โครงใส่ถังใส่ขยะ สะอาด ลิ้น / ช่องใส่ขยะไม่ชำรุด',1),(65,30,0,1,'มีระบุ กำหนดผู้รับผิดชอบพื้นที่ และกำหนดจุดจัดเก็บ/วางอุปกรณ์ สามารถมองเห็นเด่นชัด',1),(66,31,0,1,'ในพื้นที่ จะต้องไม่มีอุปกรณ์,เครื่องจักรเก่า,ขยะ หรือสิ่งของ วางโดยไม่ระบุสถานะ',1),(67,32,0,1,'มีป้ายชี้บ่งการวางของชั่วคราว มีระยะเวลา (ไม่เกินระยะเวลา)  มีผู้รับผิดชอบชัดเจน',1),(68,33,0,1,'ไม่มีสิ่งของกีดขวางทางเข้าถึงอุปกรณ์ดับเพลิง, ตู้ Main ไฟฟ้า,ตู้ Control เครื่องจักร',1),(69,34,0,1,'พนักงานแต่งกายถูกระเบียบ สวมใส่รองเท้า ไม่เหยียบส้นเท้า อุปกรณ์ SAFETY ตามที่กำหนด',1),(70,35,0,1,'ปิด Tag ขาว จากที่ถูก Audit ในเดือนที่แล้ว ครบ 100% = 1 คะแนน, ไม่ครบ = 0 คะแนน',1);
