INSERT INTO `office_criteria` (`id`, `item_no`, `max_score`, `description`, `active`) VALUES (1,1,2,'ผู้นำหน่วย นำทีมงานเข้ารับการตรวจได้ถูกต้อง เป็นระเบียบ มีวินัย และสวมปลอกแขนผู้นำหน่วย',1),(2,2,2,'Lay out ในพื้นที่ มีการ Update เป็นปัจจุบัน มีผู้เข้าใหม่ และไม่มีผู้ลาออก/โยกย้ายอยู่ในพื้นที่',1),(3,3,2,'มีมาตรฐานการทำความสะอาดพื้นที่ และตรวจตามใบ Check Sheet ครบ และมีการลงบันทึกที่ถูกต้อง',1),(4,4,3,'บอร์ด 5ส แผนก เอกสารในบอร์ด มีความเป็นปัจจุบัน ครบ ถูกต้องทุกช่อง ทุกฉบับ = 3 คะแนน, ไม่ Update 1 จุด = 2 คะแนน, มากกว่า 1 จุด = 0 คะแนน',1),(5,5,3,'มีการทำไคเซ็นต์ของพื้นที่อย่างน้อย 2 เรื่องต่อเดือนต่อพื้นที่ = 3 คะแนน, 1 เรื่อง = 2 คะแนน, ไม่ทำ/ไม่มีแสดง = 0 คะแนน',1),(6,6,3,'ด้านบนโต๊ะ กำหนด/ระบุผู้รับผิดชอบประจำโต๊ะ มีความสะอาด ไม่มีฝุ่น ไม่มีของใช้ส่วนตัววางบนโต๊ะ อนุโลมให้มีแก้วน้ำ 1 ใบ ขวดน้ำ 1 ขวด และโทรศัพท์ ที่เหลือให้เก็บไว้ในลิ้นชักของส่วนตัว',1),(7,7,3,'ใต้โต๊ะ รอบโต๊ะ ไม่มีสิ่งของไม่จำเป็นวางอยู่ ยกเว้นรองเท้าได้ 1 คู่ ถังขยะ 1 ใบ และกระดาษต่อเนื่อง สำหรับกล่องรองเท้า แฟ้มเอกสาร เอกสาร และกล่องต่างๆ ไม่ให้วาง',1),(8,8,3,'ในลิ้นชักบนสุด ต้องมีป้ายชี้จุด อุปกรณ์สำนักงาน มีการจัดวางอุปกรณ์เครื่องเขียนที่เป็นระเบียบ แยกกลุ่มการวาง ไม่รวมกับของวาง ไม่มีของส่วนตัว/ที่ไม่ใช่เครื่องเขียนอยู่ในลิ้นชัก และไม่มีโทรศัพท์มือถือ',1),(9,9,2,'สายไฟ สายคอม ไม่ระเกะระกะ มีสายรัดมัดไว้อย่างเป็นระเบียบ',1),(10,10,2,'คอมพิวเตอร์ และ Printer ต้องติดป้ายชื่อผู้รับผิดชอบไว้ชัดเจน ยกเว้น Notebook ไม่ต้องติดป้ายชื่อ',1),(11,11,2,'ชั้นวาง/ใส่เอกสาร ต้องระบุ/กำหนดผู้รับผิดชอบ ชั้นไหนวางเอกสารอะไร สามารถมองเห็นเด่นชัด',1),(12,12,3,'ตู้ / ชั้นวาง ไม่มีส่วนใดชำรุด, ไม่วางสิ่งของบนหลังตู้ สะอาด ไม่มีสติ๊กเกอร์ ไม่มีหยากไย่ และฝุ่น',1),(13,13,3,'กำหนดจุดวางของชัดเจน มีป้ายชี้จุดการวาง ถูกต้องเป็นระเบียบตามที่กำหนด มี Index ป้ายชี้วางแฟ้ม',1),(14,14,3,'มีระบุ/กำหนดผู้รับผิดชอบ ตู้ / ชั้นวาง สามารถมองเห็นเด่นชัด มีรูปผู้รับผิดชอบ',1),(15,15,2,'พื้นทางเดิน ไม่มีขยะ ไม่สกปรก ไม่มีคราบกระดาษกาว คราบกาว สก๊อตเทปต่างๆ',1),(16,16,2,'ไม่มีสายไฟระโยงระยาง, ไม่แขวนสิ่งของที่ไม่จำเป็น ยกเว้นป้ายชื่อแผนก',1),(17,17,2,'ผนัง ฝ้า เพดาน ไม่มีหยากไย่ ไม่มีรอยขีดเขียน สติ๊กเกอร์ คราบกาว รูปภาพต่างๆ ยกเว้นปฏิทินการทำงาน',1),(18,18,2,'หลอดไฟ อุปกรณ์ไฟฟ้า พัดลม/เครื่องปรับอากาศ ไม่มีชำรุด ไม่มีฝุ่น หยากไย่ คราบสกปรกต่างๆ',1),(19,19,2,'กรณีที่ต้องการวางสิ่งของบนพื้น ในพื้นที่เป็นการชั่วคราว เพื่อรอขอรับขยายในวันข้างหน้า ต้องมีป้ายชี้จุดการวางของชั่วคราว มีกำหนดระยะเวลา (ไม่เกินระยะเวลา) มีชื่อผู้รับผิดชอบชัดเจน',1),(20,20,2,'ปิด Tag จากที่ถูก Audit ในเดือนที่แล้ว ครบ 100% = 2 คะแนน, ไม่ครบ = 0 คะแนน',1),(21,21,2,'มีจุดที่เคยเป็น Comment/จุดซ้ำเนื่องจากไม่แก้ไขปิดจบ',1);
/*!40000 ALTER TABLE `office_criteria` ENABLE KEYS */;

